<?php
\defined('_JEXEC') or die;
use Joomla\CMS\HTML\HTMLHelper;
use Joomla\CMS\Language\Text;
use Joomla\CMS\Layout\LayoutHelper;
use Joomla\CMS\Router\Route;
use Joomla\CMS\Uri\Uri;
$user = $this->getCurrentUser(); $listOrder = (string) $this->state->get('list.ordering', 's.name'); $listDirn = (string) $this->state->get('list.direction', 'ASC');
?>
<form action="<?php echo Route::_('index.php?option=com_sportsmanagement&view=sportstypes'); ?>" method="post" name="adminForm" id="adminForm">
<?php if ($this->filterForm) echo LayoutHelper::render('joomla.searchtools.default', ['view' => $this]); ?>
<div class="table-responsive"><table class="table table-striped" id="sportstypesList"><thead><tr><th class="w-1 text-center"><?php echo HTMLHelper::_('grid.checkall'); ?></th><th><?php echo HTMLHelper::_('searchtools.sort','COM_SPORTSMANAGEMENT_ADMIN_SPORTSTYPES_NAME','s.name',$listDirn,$listOrder); ?></th><th class="text-center"><?php echo Text::_('COM_SPORTSMANAGEMENT_ADMIN_SPORTSTYPES_ICON'); ?></th><th class="text-center"><?php echo HTMLHelper::_('searchtools.sort','COM_SPORTSMANAGEMENT_ADMIN_SPORTSTYPES_SPORTSART','s.sportsart',$listDirn,$listOrder); ?></th><th class="w-10 text-center"><?php echo HTMLHelper::_('searchtools.sort','JSTATUS','s.published',$listDirn,$listOrder); ?></th><th class="w-10 text-center"><?php echo HTMLHelper::_('searchtools.sort','JGRID_HEADING_ORDERING','s.ordering',$listDirn,$listOrder); ?></th><th class="w-5 text-center"><?php echo HTMLHelper::_('searchtools.sort','JGRID_HEADING_ID','s.id',$listDirn,$listOrder); ?></th></tr></thead><tbody>
